class Solution {
    public boolean isPowerOfThree(int n) {
        if (n <= 0) return false;
        // 3^19 = 1,162,261,467 is the largest power of 3 that fits in a 32-bit signed int
        int maxPow3 = 1162261467;
        return maxPow3 % n == 0;
    }

    // Alternative iterative solution
    public boolean isPowerOfThreeLoop(int n) {
        if (n <= 0) return false;
        while (n % 3 == 0) {
            n /= 3;
        }
        return n == 1;
    }
}

