/**
 * Bubble Sort implementation (ascending) with input validation.
 *
 * Algorithm overview:
 * - Repeatedly compare adjacent elements and swap them if out of order.
 * - After each pass, the largest remaining element "bubbles up" to its final position.
 * - This version shortens subsequent passes to the index of the last swap and stops early if no swaps occur.
 *
 * Complexity:
 * - Time: O(n^2) worst/average, O(n) best (already sorted) due to early exit.
 * - Space: O(1) auxiliary (in-place).
 * - Stable: Yes (equal elements keep their relative order).
 *
 * Constraints enforced:
 * - Array length must be <= 100.
 * - All values must be integers in the range [-10000, 10000].
 *
 * Note:
 * - This function sorts the input array in place and also returns it.
 * - To preserve the original array, call bubbleSort([...input]) or input.slice().
 */

/**
 * Validates the input array against type and constraint requirements.
 * Throws descriptive errors if validation fails.
 * @param {any} arr
 */
function validateInputArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError('Input must be an array of integers.');
  }

  const maxLength = 100;
  if (arr.length > maxLength) {
    throw new RangeError(`Array length must be <= ${maxLength}. Received length ${arr.length}.`);
  }

  const MIN = -10000;
  const MAX = 10000;

  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];

    // Ensure the value is a primitive integer number
    if (!Number.isInteger(val)) {
      throw new TypeError(`All elements must be integers. Invalid value at index ${i}: ${val}`);
    }

    if (val < MIN || val > MAX) {
      throw new RangeError(`Element at index ${i} = ${val} is out of allowed range [${MIN}, ${MAX}].`);
    }
  }
}

/**
 * Sorts an array of integers in ascending order using Bubble Sort.
 * Performs input validation and throws errors on invalid input.
 *
 * @param {number[]} arr - Array of integers to sort (mutated in place).
 * @returns {number[]} The sorted array (same reference as input).
 */
function bubbleSort(arr) {
  // Validate input constraints
  validateInputArray(arr);

  let n = arr.length;

  // Trivial cases: 0 or 1 element are already sorted
  if (n <= 1) return arr;

  // Optimized Bubble Sort:
  // Track the last swap position to reduce the range of subsequent passes.
  // If no swaps occur in a pass, the array is already sorted.
  while (n > 1) {
    let lastSwapIndex = 0;

    for (let i = 0; i < n - 1; i++) {
      if (arr[i] > arr[i + 1]) {
        // Swap adjacent out-of-order elements
        const temp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = temp;

        lastSwapIndex = i + 1; // The array is sorted beyond this index for the next pass
      }
    }

    // If no swaps happened, the array is sorted
    if (lastSwapIndex === 0) break;

    // Reduce the pass range to the last swap position
    n = lastSwapIndex;
  }

  return arr;
}

